CREATE   VIEW [FO].[vwSKGBankAccountData]
AS
SELECT
	[ACCOUNTID],
	[ACCOUNTSTATEMENTDATE],
	[ACCOUNTSTATEMENTNUM],
	[CURRENCYCODE],
	[ENDINGBALANCE],
	[RECONCILEDATE],
	[CANCELDATE],
	[COMPANY],
	[BANKACCOUNTTABLE_ACCOUNTID],
	[IMPORTHITRATE],
	[BANKNAME],
	[IMPORTCOUNT],
	[IMPORTUNMATCHEDCOUNT],
	[UNRECONCILEDAMOUNT],
	[PARTITION],
	[DATAAREAID]
FROM [Ext].[PBI04_FO_vwSKGBankAccountData]
